import React, { useState } from 'react';
import { deleteCamera, updateCamera } from '../services/api';
import { useApp } from '../context/AppContext';

const detColors = {
  Normal:       '#22c55e',
  Phone:        '#60a5fa',
  Medical_Mask: '#34d399',
  Fire:         '#ef4444',
  Smoke:        '#94a3b8',
  Gun:          '#f87171',
  Knife:        '#facc15',
  Falling:      '#a78bfa',
  Violence:     '#a855f7',
  Theft_Mask:   '#fbbf24'
};

const threatBorder = {
  Fire:     '#7f1d1d',
  Violence: '#7f1d3f',
  Gun:      '#7f1d1d',
  Knife:    '#7f6d00'
};

export default function CameraCard({ camera, showControls = false }) {
  const { refreshCameras } = useApp();
  const [deleting, setDeleting] = useState(false);
  const [toggling, setToggling] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [imgError, setImgError] = useState(false);

  const isOnline  = camera.status === 'online';
  const lastClass = camera.last_class || 'Normal';
  const lastConf  = camera.last_conf  || 0.92;
  const detColor  = detColors[lastClass] || '#22c55e';
  const borderCol = isOnline ? (threatBorder[lastClass] || '#1e2d47') : '#1e2d47';

  const streamUrl = `http://localhost:8000/cameras/${camera.id}/stream`;

  const handleDelete = async () => {
    if (!window.confirm(`Delete ${camera.name}?`)) return;
    setDeleting(true);
    try {
      await deleteCamera(camera.id);
      await refreshCameras();
    } catch (err) {
      alert('Failed to delete camera');
    } finally {
      setDeleting(false);
    }
  };

  const handleToggle = async () => {
    setToggling(true);
    try {
      await updateCamera(camera.id, {
        status: isOnline ? 'offline' : 'online'
      });
      await refreshCameras();
    } catch (err) {
      alert('Failed to update camera');
    } finally {
      setToggling(false);
      setShowMenu(false);
    }
  };

  const handleFullscreen = () => {
    window.open(streamUrl, '_blank', 'width=960,height=620');
  };

  const handleScreenshot = () => {
    alert(`Screenshot captured from ${camera.name}`);
  };

  return (
    <div style={{
      background: '#151d2e',
      border: `1px solid ${borderCol}`,
      borderRadius: 8,
      overflow: 'hidden',
      opacity: deleting ? 0.5 : 1,
      position: 'relative',
      transition: 'opacity .3s'
    }}>

      {/* ── HEADER ───────────────────────────────────────────── */}
      <div style={{
        display: 'flex', justifyContent: 'space-between',
        alignItems: 'center', padding: '6px 10px',
        background: '#1a2340'
      }}>
        <span style={{ fontSize: 10, fontWeight: 600, color: '#e2e8f0' }}>
          {camera.name}
        </span>
        {isOnline ? (
          <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#22c55e' }}>
            <span style={{
              width: 6, height: 6, borderRadius: '50%',
              background: '#22c55e', display: 'inline-block',
              animation: 'livePulse 1.5s infinite'
            }} />
            Live
            <style>{`@keyframes livePulse{0%,100%{opacity:1}50%{opacity:.3}}`}</style>
          </span>
        ) : (
          <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#64748b' }}>
            <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#64748b', display: 'inline-block' }} />
            Offline
          </span>
        )}
      </div>

      {/* ── FEED ─────────────────────────────────────────────── */}
      <div style={{
        height: 120, background: '#080f1a',
        position: 'relative',
        display: 'flex', alignItems: 'center',
        justifyContent: 'center', overflow: 'hidden'
      }}>
        {isOnline ? (
          <>
            {/* Real webcam stream */}
            {!imgError ? (
              <img
                src={streamUrl}
                alt={camera.name}
                style={{
                  width: '100%', height: '100%',
                  objectFit: 'cover', display: 'block'
                }}
                onError={() => setImgError(true)}
              />
            ) : (
              /* Fallback if stream fails */
              <div style={{
                display: 'flex', flexDirection: 'column',
                alignItems: 'center', gap: 4
              }}>
                <span style={{ fontSize: 22 }}>📷</span>
                <span style={{ fontSize: 10, color: '#64748b' }}>Stream unavailable</span>
                <button
                  onClick={() => setImgError(false)}
                  style={{
                    background: '#1e3a5f', border: '1px solid #253550',
                    color: '#60a5fa', fontSize: 9, padding: '3px 8px',
                    borderRadius: 4, cursor: 'pointer', marginTop: 2
                  }}
                >
                  Retry
                </button>
              </div>
            )}

            {/* Detection overlay box */}
            <div style={{
              position: 'absolute', top: '12%', left: '8%',
              border: `2px solid ${detColor}`, borderRadius: 4,
              padding: '2px 6px', fontSize: 9, fontWeight: 700,
              color: detColor, background: `${detColor}22`,
              pointerEvents: 'none'
            }}>
              {lastClass} {lastConf}
            </div>

            {/* Location badge */}
            {camera.location && (
              <div style={{
                position: 'absolute', bottom: 6, left: 6,
                background: 'rgba(0,0,0,.6)', color: '#94a3b8',
                fontSize: 8, padding: '2px 6px', borderRadius: 3
              }}>
                📍 {camera.location}
              </div>
            )}
          </>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
            <span style={{ fontSize: 24, opacity: .4 }}>📷</span>
            <span style={{ fontSize: 11, color: '#64748b' }}>[ Offline ]</span>
          </div>
        )}
      </div>

      {/* ── FOOTER ───────────────────────────────────────────── */}
      <div style={{
        display: 'flex', justifyContent: 'space-between',
        alignItems: 'center', padding: '5px 10px',
        background: '#1a2340', position: 'relative'
      }}>

        {/* Screenshot button */}
        <span
          title="Screenshot"
          onClick={handleScreenshot}
          style={{
            fontSize: 15, cursor: 'pointer',
            color: '#64748b', padding: '2px 4px',
            borderRadius: 4, transition: 'color .15s'
          }}
          onMouseEnter={e => e.currentTarget.style.color = '#60a5fa'}
          onMouseLeave={e => e.currentTarget.style.color = '#64748b'}
        >
          📷
        </span>

        {/* Fullscreen button */}
        <span
          title="Open stream in new window"
          onClick={handleFullscreen}
          style={{
            fontSize: 15, cursor: 'pointer',
            color: '#64748b', padding: '2px 4px',
            borderRadius: 4, transition: 'color .15s'
          }}
          onMouseEnter={e => e.currentTarget.style.color = '#60a5fa'}
          onMouseLeave={e => e.currentTarget.style.color = '#64748b'}
        >
          ⛶
        </span>

        {/* Options menu button */}
        <span
          title="Options"
          onClick={() => setShowMenu(!showMenu)}
          style={{
            fontSize: 16, cursor: 'pointer', fontWeight: 700,
            color: showMenu ? '#60a5fa' : '#64748b',
            padding: '2px 6px', borderRadius: 4,
            transition: 'color .15s'
          }}
        >
          ⋯
        </span>

        {/* Signal bars */}
        <div style={{ display: 'flex', gap: 2, alignItems: 'flex-end' }}>
          {[4, 6, 8, 10].map((h, i) => (
            <span key={i} style={{
              width: 3, height: h,
              background: isOnline ? '#22c55e' : '#253550',
              borderRadius: 1, display: 'block',
              opacity: isOnline ? 1 : 0.4
            }} />
          ))}
        </div>

        {/* Dropdown menu */}
        {showMenu && (
          <div style={{
            position: 'absolute', bottom: '110%', right: 0,
            background: '#0f172a', border: '1px solid #253550',
            borderRadius: 8, overflow: 'hidden', zIndex: 200,
            minWidth: 160, boxShadow: '0 8px 24px rgba(0,0,0,.7)'
          }}>
            {/* Toggle online/offline */}
            <div
              onClick={handleToggle}
              style={{
                padding: '10px 14px', fontSize: 11,
                color: isOnline ? '#fbbf24' : '#4ade80',
                cursor: toggling ? 'not-allowed' : 'pointer',
                borderBottom: '1px solid #1e2d47',
                display: 'flex', alignItems: 'center', gap: 6
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#1a2340'}
              onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
            >
              {toggling
                ? '⏳ Updating...'
                : isOnline
                  ? '⏸ Set Offline'
                  : '▶ Set Online'}
            </div>

            {/* Open stream */}
            <div
              onClick={handleFullscreen}
              style={{
                padding: '10px 14px', fontSize: 11,
                color: '#60a5fa', cursor: 'pointer',
                borderBottom: '1px solid #1e2d47',
                display: 'flex', alignItems: 'center', gap: 6
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#1a2340'}
              onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
            >
              🔗 Open Stream
            </div>

            {/* Delete camera */}
            <div
              onClick={handleDelete}
              style={{
                padding: '10px 14px', fontSize: 11,
                color: '#f87171',
                cursor: deleting ? 'not-allowed' : 'pointer',
                display: 'flex', alignItems: 'center', gap: 6
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#1a2340'}
              onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
            >
              🗑 Delete Camera
            </div>
          </div>
        )}
      </div>

      {/* ── DETECTIONS BADGE ─────────────────────────────────── */}
      {camera.detections > 0 && (
        <div style={{
          position: 'absolute', top: 32, right: 6,
          background: '#1e3a5f', color: '#60a5fa',
          fontSize: 9, fontWeight: 700,
          padding: '2px 6px', borderRadius: 4,
          pointerEvents: 'none'
        }}>
          {camera.detections} det
        </div>
      )}

    </div>
  );
}
